$('play').onclick=()=>{if(mode!=='paused')reset();mode='playing';$('veil').style.display='none';$('crosshair').style.display='block';if(!audio){try{audio=new(window.AudioContext||window.webkitAudioContext)()}catch{}}audio?.resume();try{let result=canvas.requestPointerLock?.();result?.catch(()=>tell('Souris indisponible : utilisez les flèches pour tourner.'))}catch{tell('Utilisez les flèches pour tourner.')}tell('Brisez les sceaux avec E. M : carte de la forteresse.');hud()};
$('sound').onclick=()=>{sound=!sound;$('sound').textContent='SON : '+(sound?'OUI':'NON')};document.addEventListener('pointerlockchange',()=>{if(document.pointerLockElement!==canvas)pause()});document.addEventListener('mousemove',e=>{if(mode==='playing'&&document.pointerLockElement===canvas)p.a+=e.movementX*.0025});canvas.addEventListener('mousedown',e=>{if(e.button===0)shoot()});document.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if([' ','arrowleft','arrowright','arrowup','arrowdown'].includes(k))e.preventDefault();keys[k]=true;if(mode==='playing'){if(k==='1')weapon=0;if(k==='2')weapon=1;if(k==='e'&&!e.repeat)interact();if(k==='m'&&!e.repeat)mapShown=!mapShown;if(k==='escape'){pause();document.exitPointerLock?.()}}});document.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>{pause();keys={}});document.addEventListener('visibilitychange',()=>{if(document.hidden)pause()});
